// Compound phase style: enter (opacity+translate+scale+blur) with optional
// hold (no exit fade — for the final beat). `start`/`dur` are LOCAL frames.
function phase(
  frame: number,
  vfps: number,
  start: number,
  dur: number,
  opts: {
    preset?: "SNAPPY" | "ELASTIC" | "LIQUID" | "GENTLE" | "OVERDAMPED";
    ty?: number;
    tx?: number;
    scaleFrom?: number;
    blurFrom?: number;
    inDelay?: number;
    exitFrames?: number;
    hold?: boolean;
  } = {}
): { opacity: number; transform: string; filter: string } {
  const {
    preset = "SNAPPY",
    ty = 30,
    tx = 0,
    scaleFrom = 0.94,
    blurFrom = 6,
    inDelay = 0,
    exitFrames = 14,
    hold = false,
  } = opts;
  const local = frame - start;
  const enter = springIn(local, vfps, inDelay, preset);
  const out = hold
    ? 1
    : interpolate(local, [dur - exitFrames, dur], [1, 0], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
  const opacity = Math.max(0, Math.min(enter, out));
  const tyN = interpolate(enter, [0, 1], [ty, 0]);
  const txN = interpolate(enter, [0, 1], [tx, 0]);
  const sc = interpolate(enter, [0, 1], [scaleFrom, 1]);
  const bl = interpolate(enter, [0, 1], [blurFrom, 0]);
  return {
    opacity,
    transform: `translate(${txN}px, ${tyN}px) scale(${sc})`,
    filter: `blur(${bl}px)`,
  };
}

