const ToolGrid: React.FC<{ base: number; frame: number; vfps: number }> = ({ base, frame, vfps }) => {
  const cols = 4;
  const rows = 3;
  const cell = base * 0.07;
  const gap = base * 0.016;
  const tiles: React.ReactNode[] = [];
  for (let i = 0; i < cols * rows; i++) {
    const p = staggeredSpring(frame, vfps, i, 18, 4, "GENTLE");
    tiles.push(
      <div
        key={i}
        style={{
          width: cell,
          height: cell,
          borderRadius: base * 0.01,
          background: C.card,
          border: `1px solid ${i % 5 === 0 ? ACCENT : C.border}`,
          opacity: p * 0.96,
          transform: `scale(${interpolate(p, [0, 1], [0.6, 1])})`,
        }}
      />
    );
  }
  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: `repeat(${cols}, ${cell}px)`,
        gap,
      }}
    >
      {tiles}
    </div>
  );
};

